#!/usr/bin/env python3
"""Week 6 · harness for Task 3. Do not edit this file.

Synthetic baskets with planted frequent pairs, fixed seed, so everyone compares.

    items      2,000
    baskets    20,000, average 20 items, Zipf-popular items
    support    50
    scored     peak pair counters held
    checked    exactly the same frequent pairs as the baseline

    python3 bench.py
    python3 bench.py --yours
"""
import argparse, random, time

SEED, ITEMS, BASKETS, AVG, SUPPORT = 246, 2_000, 20_000, 20, 50


def build(seed=SEED):
    rng = random.Random(seed)
    items = list(range(ITEMS))
    weights = [1 / (i + 1) ** 0.8 for i in range(ITEMS)]
    # a few pairs that genuinely go together
    planted = [(rng.randrange(300), rng.randrange(300)) for _ in range(25)]
    planted = [(a, b) for a, b in planted if a != b]

    baskets = []
    for _ in range(BASKETS):
        k = max(2, int(rng.gauss(AVG, 4)))
        basket = set(rng.choices(items, weights, k=k))
        if rng.random() < 0.08:
            a, b = rng.choice(planted)
            basket.update((a, b))
        baskets.append(basket)
    return baskets


def run(cls, label, baskets, reference=None):
    algo = cls(SUPPORT)
    t0 = time.perf_counter()
    pairs = algo.run(baskets)
    elapsed = time.perf_counter() - t0
    peak = algo.peak_counters

    same = "-"
    if reference is not None:
        missing = len(set(reference) - set(pairs))
        extra = len(set(pairs) - set(reference))
        same = f"missing {missing}, extra {extra}"
    print(f"  {label:<12} pairs {len(pairs):>5}   peak counters {peak:>10,}   "
          f"{elapsed:>6.2f}s   {same}")
    return {"pairs": pairs, "peak": peak, "time": elapsed}


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--yours", action="store_true")
    a = p.parse_args()

    baskets = build()
    print(f"\n  {len(baskets):,} baskets, {ITEMS:,} items, support {SUPPORT}\n")

    from task3_pcy import PlainApriori
    base = run(PlainApriori, "baseline", baskets)

    if a.yours:
        from task3_pcy import YourAlgorithm
        mine = run(YourAlgorithm, "yours", baskets, base["pairs"])
        print()
        if set(mine["pairs"]) != set(base["pairs"]):
            print("   FAIL  different frequent pairs. Correctness first.")
        else:
            cut = 1 - mine["peak"] / base["peak"]
            print(f"   ok    same frequent pairs")
            print(f"   peak counters cut by {cut:.1%}  "
                  f"({mine['peak']:,} from {base['peak']:,})")
            grade = ("strong" if cut >= 0.70 else
                     "good" if cut >= 0.40 else
                     "pass" if cut > 0.05 else "not yet")
            print(f"\n   -> {grade}")
    print()


if __name__ == "__main__":
    main()
